  r"""const p=NUMS(prices).filter(x=>x>0);if(!p.length)return 'Enter at least one price.';const sh=p.reduce((s,x)=>s+amt/x,0),inv=amt*p.length,last=p[p.length-1],mean=p.reduce((s,x)=>s+x,0)/p.length;return [['Average cost per share',M(inv/sh)],['Shares bought',N(sh,4)],['Total invested',M(inv)],['Value at last price',M(sh*last)],['Gain / loss',M(sh*last-inv)],['Simple average price',M(mean)]];""",
